  }

  // Count the number of trailing zeros (rightmost contiguous zeros)
  uint64_t trailing_zeros = 0;
  for (int i = n_bits_; i < 64; ++i) {
    if (binary[i] == 0) {
      trailing_zeros++;
    } else {
      break;
    }
  }

  // Increment trailing_zeros by 1 to match the algorithm description
  trailing_zeros += 1;

  // Split the trailing_zeros into dense and overflow parts
  // Dense part: last DENSE_BUCKET_SIZE bits
  // Overflow part: remaining bits
  std::bitset<DENSE_BUCKET_SIZE> dense_part;
  std::bitset<OVERFLOW_BUCKET_SIZE> overflow_part;

  // Set the dense part (lower bits)
  for (int i = 0; i < DENSE_BUCKET_SIZE; ++i) {
    if (i < 64 && (trailing_zeros & (1ULL << i))) {
      dense_part.set(i);
    }
